import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './AddProduct.css';

const AddProduct = () => {
  const [product, setProduct] = useState({
    name: '',
    price: '',
    quantity: '',
    description: '',
    listingDate: '',
    user_id: '',
    selectedProduct: '', // This will hold the selected product's name
  });
  const [errorMessage, setErrorMessage] = useState('');
  const [productList, setProductList] = useState([]); // Store the list of product names
  const [searchQuery, setSearchQuery] = useState(''); // To filter products by name

  // Fetch product names from the API on component mount
  useEffect(() => {
    const fetchProductNames = async () => {
      try {
        const response = await axios.get('http://localhost:8080/api/product-names'); // Endpoint to fetch product names
        const products = response.data;

        // Set the product list with the fetched product names
        setProductList(products);
      } catch (error) {
        console.error('Error fetching product names:', error);
        setErrorMessage('Failed to load product names.');
      }
    };

    fetchProductNames();
  }, []);

  // Handle changes in the input fields
  const handleChange = (e) => {
    const { name, value } = e.target;
    setProduct({
      ...product,
      [name]: value,
    });
  };

  // Handle submit
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!product.user_id || !product.selectedProduct) {
      alert('Please enter a valid user ID and select a product.');
      return;
    }

    try {
      await axios.post(
        'http://localhost:8080/api/products',
        {
          name: product.selectedProduct, // Send the selected product name
          price: product.price,
          quantity: product.quantity,
          description: product.description,
          listingDate: product.listingDate,
          user: { id: product.user_id },
        },
        {
          headers: { 'Content-Type': 'application/json' },
        }
      );

      alert('Product added successfully!');
      setProduct({
        name: '',
        price: '',
        quantity: '',
        description: '',
        listingDate: '',
        user_id: '',
        selectedProduct: '',
      });
    } catch (error) {
      console.error('Error adding product:', error);
      alert('Failed to add product.');
      setErrorMessage(error.response?.data?.message || 'An error occurred.');
    }
  };

  // Filter products based on search query
  const filteredProducts = productList.filter((prod) =>
    prod.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="add-product-container">
      <h1>Add Product</h1>
      <form onSubmit={handleSubmit} className="add-product-form">
        <div className="form-group">
          <label htmlFor="user_id">User ID</label>
          <input
            type="number"
            name="user_id"
            id="user_id"
            value={product.user_id}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group">
          <label htmlFor="selectedProduct">Product Name</label>
          <input
            type="text"
            name="searchQuery"
            id="searchQuery"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)} // Update search query
            placeholder="Search for a product"
          />
          <select
            name="selectedProduct"
            id="selectedProduct"
            value={product.selectedProduct}
            onChange={handleChange}
            required
          >
            <option value="">Select a product</option>
            {filteredProducts.map((prod) => (
              <option key={prod.id} value={prod.name}>
                {prod.name}
              </option>
            ))}
          </select>
        </div>
        <div className="form-group">
          <label htmlFor="price">Price</label>
          <input
            type="number"
            name="price"
            id="price"
            value={product.price}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group">
          <label htmlFor="quantity">Quantity</label>
          <input
            type="number"
            name="quantity"
            id="quantity"
            value={product.quantity}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group">
          <label htmlFor="description">Description</label>
          <textarea
            name="description"
            id="description"
            value={product.description}
            onChange={handleChange}
            required
          />
        </div>
        <div className="form-group">
          <label htmlFor="listingDate">Listing Date</label>
          <input
            type="date"
            name="listingDate"
            id="listingDate"
            value={product.listingDate}
            onChange={handleChange}
            required
          />
        </div>
        <button type="submit" className="submit-button">Add Product</button>
      </form>
      {errorMessage && <p className="error-message">{errorMessage}</p>}
    </div>
  );
};

export default AddProduct;
